                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(7)%off(idx), sidx(7)%off(idx+1)-1
                        jdet = sidx(7)%perm(jj); v = bt4d_excits(jdet,2); w = bt4d_excits(jdet,3); u = bt4d_excits(jdet,8)
                        IX(:) = IX(:) + (-1d0 * bt4d_amps(jdet)) * V2C_oovv_1023(:,u,v,w)
                     end do
                     end if
                     idx = lk(10)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(8)%off(idx), sidx(8)%off(idx+1)-1
                        jdet = sidx(8)%perm(jj); v = bt4d_excits(jdet,2); w = bt4d_excits(jdet,3); u = bt4d_excits(jdet,7)
                        IX(:) = IX(:) + (1d0 * bt4d_amps(jdet)) * V2C_oovv_1023(:,u,v,w)
                     end do
                     end if
                     idx = lk(11)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(9)%off(idx), sidx(9)%off(idx+1)-1
                        jdet = sidx(9)%perm(jj); v = bt4d_excits(jdet,2); w = bt4d_excits(jdet,3); u = bt4d_excits(jdet,6)
                        IX(:) = IX(:) + (-1d0 * bt4d_amps(jdet)) * V2C_oovv_1023(:,u,v,w)
                     end do
