                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(10)%off(idx), sidx(10)%off(idx+1)-1
                        jdet = sidx(10)%perm(jj); v = bt4c_excits(jdet,2); w = bt4c_excits(jdet,4); u = bt4c_excits(jdet,6)
                        IX(:) = IX(:) + (1d0 * bt4c_amps(jdet)) * V2B_oovv_1023(:,u,v,w)
