                        jdet = sidx(14)%perm(jj); v = bt4c_excits(jdet,1); w = bt4c_excits(jdet,4); u = bt4c_excits(jdet,6)
                        IX(:) = IX(:) + (-1d0 * bt4c_amps(jdet)) * V2B_oovv_1023(:,u,v,w)
                     end do
                     end if
                     idx = lk(17)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(15)%off(idx), sidx(15)%off(idx+1)-1
                        jdet = sidx(15)%perm(jj); v = bt4c_excits(jdet,1); w = bt4c_excits(jdet,4); u = bt4c_excits(jdet,5)
                        IX(:) = IX(:) + (1d0 * bt4c_amps(jdet)) * V2B_oovv_1023(:,u,v,w)
                     end do
