                        jdet = sidx(16)%perm(jj); v = bt4c_excits(jdet,1); w = bt4c_excits(jdet,3); u = bt4c_excits(jdet,6)
                        IX(:) = IX(:) + (1d0 * bt4c_amps(jdet)) * V2B_oovv_1023(:,u,v,w)
                     end do
                     end if
                     idx = lk(19)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
