                  end do
                  !$omp end do
                  deallocate(IX)
                  !$omp end parallel
                  !!!! 11 passes on T4 sorted by columns (1,2,5,6,8)
                  tdims(1:5) = (/nua,nub,noa,nob,nob/)
                  tchain(1:5) = (/.false.,.false.,.false.,.false.,.true./)
                  call sort_pspace(t4d_excits, t4d_amps, n4abbb, 5, (/1,2,5,6,8/), tdims, tchain, tnblk, tkey, toff, resid)
                  ! q blocks grouped by their slice letters (counting sort of the blocks, T4 not moved)
