                        do tt = 1, nc
                           kdx = bord(k0+tt-1)
                           do idet = toff(kdx), toff(kdx+1)-1
                              c = t4d_excits(idet,3); d = t4d_excits(idet,4); k = t4d_excits(idet,7);
