                     idx = lk(18)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(16)%off(idx), sidx(16)%off(idx+1)-1
                        jdet = sidx(16)%perm(jj); v = bt4c_excits(jdet,1); w = bt4c_excits(jdet,3); u = bt4c_excits(jdet,6)
                        IX(:) = IX(:) + (1d0 * bt4c_amps(jdet)) * V2B_oovv_1023(:,u,v,w)
                     end do
                     end if
                     idx = lk(19)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(17)%off(idx), sidx(17)%off(idx+1)-1
                        jdet = sidx(17)%perm(jj); v = bt4c_excits(jdet,1); w = bt4c_excits(jdet,3); u = bt4c_excits(jdet,5)
                        IX(:) = IX(:) + (-1d0 * bt4c_amps(jdet)) * V2B_oovv_1023(:,u,v,w)
                     end do
