                     end if
                  end do
                  !$omp end do
                  deallocate(IX)
                  !$omp end parallel
                  !!!! 11 passes on T4 sorted by columns (1,2,5,7,8)
                  tdims(1:5) = (/nua,nub,noa,nob,nob/)
                  tchain(1:5) = (/.false.,.false.,.false.,.false.,.true./)
                  call sort_pspace(t4d_excits, t4d_amps, n4abbb, 5, (/1,2,5,7,8/), tdims, tchain, tnblk, tkey, toff, resid)
                  ! q blocks grouped by their slice letters (counting sort of the blocks, T4 not moved)
                  allocate(trun(nua*noa+1), tcur(nua*noa), bord(tnblk))
                  trun = 0
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     tt = (t4d_excits(toff(kdx),1)-1)*noa + t4d_excits(toff(kdx),5)
                     trun(tt+1) = trun(tt+1) + 1
                  end do
                  trun(1) = 1
                  do tt = 1, nua*noa
                     trun(tt+1) = trun(tt) + trun(tt+1)
                  end do
                  tcur(:) = trun(1:nua*noa)
                  do kdx = 1, tnblk
