                        end do
                        RB(:,1:nc) = matmul(H2B_vovo_1203(:,:,a,l), GB(:,1:nc))
                        do tt = 1, nc
                           kdx = bord(k0+tt-1)
                           do idet = toff(kdx), toff(kdx+1)-1
                              c = t4d_excits(idet,3); d = t4d_excits(idet,4); j = t4d_excits(idet,6);
                              val = 0.0d0
