                     do jj = sidx(12)%off(idx), sidx(12)%off(idx+1)-1
                        jdet = sidx(12)%perm(jj); v = bt4c_excits(jdet,2); w = bt4c_excits(jdet,3); u = bt4c_excits(jdet,6)
                        IX(:) = IX(:) + (-1d0 * bt4c_amps(jdet)) * V2B_oovv_1023(:,u,v,w)
                     end do
                     end if
                     idx = lk(15)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(13)%off(idx), sidx(13)%off(idx+1)-1
                        jdet = sidx(13)%perm(jj); v = bt4c_excits(jdet,2); w = bt4c_excits(jdet,3); u = bt4c_excits(jdet,5)
                        IX(:) = IX(:) + (1d0 * bt4c_amps(jdet)) * V2B_oovv_1023(:,u,v,w)
                     end do
