                     a = t4d_excits(idet,1); d = t4d_excits(idet,4); i = t4d_excits(idet,5); k = t4d_excits(idet,7); l = t4d_excits(idet,8);
                     anyx = .false.
                     idx = lk(2)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jdet = off_vabb0112(idx), off_vabb0112(idx+1)-1
                        u = vabb0112_excits(jdet,5); v = vabb0112_excits(jdet,6)
                        IX(:) = IX(:) + (1d0 * vabb0112_amps(jdet)) * H2B_vovv_1023(:,a,u,v)
                     end do
                     end if
                     if (anyx) then
                     do idet = toff(kdx), toff(kdx+1)-1
                        b = t4d_excits(idet,2); c = t4d_excits(idet,3); j = t4d_excits(idet,6);
                        val = 0.0d0
                        do x = 1, nob
                           val = val + IX(x) * t2c(c,b,j,x)
                        end do
                        resid(idet) = resid(idet) - 1d0 * val
                     end do
                     end if
                     ! -0.25 * I3C_vovooo(axbilj) * tbb(dcxk), q = (a,d,i,k,l), sign -1
                     idet = toff(kdx)
                     a = t4d_excits(idet,1); d = t4d_excits(idet,4); i = t4d_excits(idet,5); k = t4d_excits(idet,7); l = t4d_excits(idet,8);
                     anyx = .false.
                     idx = lk(3)
                     if (idx/=0) then
