                     do jj = sidx(1)%off(idx), sidx(1)%off(idx+1)-1
                        jdet = sidx(1)%perm(jj); v = bt4d_excits(jdet,3); w = bt4d_excits(jdet,4); u = bt4d_excits(jdet,8)
                        IX(:) = IX(:) + (-1d0 * bt4d_amps(jdet)) * V2C_oovv_1023(:,u,v,w)
