                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     tt = (t4d_excits(toff(kdx),4)-1)*nob + t4d_excits(toff(kdx),8)
                     bord(tcur(tt)) = kdx; tcur(tt) = tcur(tt) + 1
                  end do
                  !$omp parallel default(shared) private(GB,RB,val,a,b,c,d,i,j,k,l,x,u,v,w,z,r,s,t,g,h,idet,kdx,irun,k0,nc,tt)
                  allocate(GB(noa,MAXC), RB(nua,MAXC))
                  !$omp do schedule(dynamic,4)
                  do irun = 1, nub*nob
                     do k0 = trun(irun), trun(irun+1)-1, MAXC
                        nc = min(MAXC, trun(irun+1)-k0)
                        do tt = 1, nc
                           idet = toff(bord(k0+tt-1))
                           a = t4d_excits(idet,1); c = t4d_excits(idet,3); d = t4d_excits(idet,4); k = t4d_excits(idet,7); l = t4d_excits(idet,8);
                           do u = 1, noa
                              GB(u,tt) = 1d0 * t2b(a,c,u,k)
                           end do
                        end do
                        RB(:,1:nc) = matmul(H2B_ovvo_2013(:,:,d,l), GB(:,1:nc))
                        do tt = 1, nc
                           kdx = bord(k0+tt-1)
                           do idet = toff(kdx), toff(kdx+1)-1
                              b = t4d_excits(idet,2); i = t4d_excits(idet,5); j = t4d_excits(idet,6);
                              val = 0.0d0
                              do x = 1, nua
                                 val = val + RB(x,tt) * t2b(x,b,i,j)
                              end do
                              resid(idet) = resid(idet) - 1d0 * val
                           end do
                        end do
                     end do
                  end do
                  !$omp end do
                  deallocate(GB, RB)
                  !$omp end parallel
                  deallocate(trun, tcur, bord)
                  !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,jj,kdx,idx,xx,yy,ixv,nsrc,idx2,jdet2,jj2,lk,mark,need,nneed,nn,anyx)
                  allocate(IX(nua))
                  !$omp do schedule(dynamic,8)
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     idet = toff(kdx)
                     a = t4d_excits(idet,1); c = t4d_excits(idet,3); d = t4d_excits(idet,4); k = t4d_excits(idet,7); l = t4d_excits(idet,8);
                     lk(1) = pspace_find(sidx(18)%key, sidx(18)%nblock, pspace_key((/a,c,d,k,l/), 5, sidx(18)%dims, sidx(18)%chain))
                     lk(2) = pspace_find(sidx(19)%key, sidx(19)%nblock, pspace_key((/a,c,d,k,l/), 5, sidx(19)%dims, sidx(19)%chain))
                     lk(3) = pspace_find(sidx(20)%key, sidx(20)%nblock, pspace_key((/a,c,d,k,l/), 5, sidx(20)%dims, sidx(20)%chain))
                     lk(4) = pspace_find(sidx(21)%key, sidx(21)%nblock, pspace_key((/a,c,d,k,l/), 5, sidx(21)%dims, sidx(21)%chain))
                     lk(5) = pspace_find(sidx(22)%key, sidx(22)%nblock, pspace_key((/a,c,d,k,l/), 5, sidx(22)%dims, sidx(22)%chain))
                     lk(6) = pspace_find(sidx(23)%key, sidx(23)%nblock, pspace_key((/a,c,d,k,l/), 5, sidx(23)%dims, sidx(23)%chain))
                     lk(7) = pspace_find(sidx(24)%key, sidx(24)%nblock, pspace_key((/a,c,d,k,l/), 5, sidx(24)%dims, sidx(24)%chain))
                     lk(8) = pspace_find(sidx(25)%key, sidx(25)%nblock, pspace_key((/a,c,d,k,l/), 5, sidx(25)%dims, sidx(25)%chain))
                     lk(9) = pspace_find(sidx(26)%key, sidx(26)%nblock, pspace_key((/a,c,d,k,l/), 5, sidx(26)%dims, sidx(26)%chain))
                     lk(10) = pspace_find(sidx(27)%key, sidx(27)%nblock, pspace_key((/a,c,d,k,l/), 5, sidx(27)%dims, sidx(27)%chain))
                     lk(11) = pspace_find(sidx(28)%key, sidx(28)%nblock, pspace_key((/a,c,d,k,l/), 5, sidx(28)%dims, sidx(28)%chain))
                     ! +0.25 * I3C_vvvvoo(acdxkl) * tab(xbij), q = (a,c,d,k,l), sign +1
