                     anyx = .false.
                     idx = lk(1)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(18)%off(idx), sidx(18)%off(idx+1)-1
                        jdet = sidx(18)%perm(jj); w = bt4d_excits(jdet,4); u = bt4d_excits(jdet,5); v = bt4d_excits(jdet,8)
                        IX(:) = IX(:) + (-1d0 * bt4d_amps(jdet)) * V2B_oovv_2013(:,u,v,w)
                     end do
                     end if
                     idx = lk(2)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(19)%off(idx), sidx(19)%off(idx+1)-1
                        jdet = sidx(19)%perm(jj); w = bt4d_excits(jdet,4); u = bt4d_excits(jdet,5); v = bt4d_excits(jdet,7)
                        IX(:) = IX(:) + (1d0 * bt4d_amps(jdet)) * V2B_oovv_2013(:,u,v,w)
                     end do
