                     lk(8) = pspace_find(sidx(36)%key, sidx(36)%nblock, pspace_key((/a,b,c,i,j/), 5, sidx(36)%dims, sidx(36)%chain))
                     lk(9) = pspace_find(sidx(37)%key, sidx(37)%nblock, pspace_key((/a,b,c,i,j/), 5, sidx(37)%dims, sidx(37)%chain))
