                     lk(16) = pspace_find(sidx(44)%key, sidx(44)%nblock, pspace_key((/a,b,c,i,j/), 5, sidx(44)%dims, sidx(44)%chain))
                     lk(17) = pspace_find(sidx(45)%key, sidx(45)%nblock, pspace_key((/a,b,c,i,j/), 5, sidx(45)%dims, sidx(45)%chain))
                     ! +0.25 * I3C_vvvoov(abdijx) * tbb(xclk), q = (a,b,c,i,j), sign -1
