                  !$omp parallel default(shared) private(GB,RB,val,a,b,c,d,i,j,k,l,x,u,v,w,z,r,s,t,g,h,idet,kdx,irun,k0,nc,tt)
                  allocate(GB(nob,MAXC), RB(nub,MAXC))
                  !$omp do schedule(dynamic,4)
                  do irun = 1, nub*nob
                     do k0 = trun(irun), trun(irun+1)-1, MAXC
                        nc = min(MAXC, trun(irun+1)-k0)
                        do tt = 1, nc
                           idet = toff(bord(k0+tt-1))
                           a = t4d_excits(idet,1); b = t4d_excits(idet,2); d = t4d_excits(idet,4); i = t4d_excits(idet,5); j = t4d_excits(idet,6);
                           do u = 1, nob
                              GB(u,tt) = 1d0 * t2b(a,b,i,u)
                           end do
                        end do
                        RB(:,1:nc) = matmul(H2C_voov_3102(:,:,d,j), GB(:,1:nc))
                        do tt = 1, nc
                           kdx = bord(k0+tt-1)
                           do idet = toff(kdx), toff(kdx+1)-1
                              c = t4d_excits(idet,3); k = t4d_excits(idet,7); l = t4d_excits(idet,8);
                              val = 0.0d0
                              do x = 1, nub
                                 val = val + RB(x,tt) * t2c(x,c,l,k)
                              end do
                              resid(idet) = resid(idet) + 1d0 * val
                           end do
                        end do
                     end do
                  end do
                  !$omp end do
                  deallocate(GB, RB)
                  !$omp end parallel
                  deallocate(trun, tcur, bord)
                  !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,jj,kdx,idx,xx,yy,ixv,nsrc,idx2,jdet2,jj2,lk,mark,need,nneed,nn,anyx)
                  allocate(IX(nub))
                  !$omp do schedule(dynamic,8)
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     idet = toff(kdx)
                     a = t4d_excits(idet,1); b = t4d_excits(idet,2); d = t4d_excits(idet,4); i = t4d_excits(idet,5); j = t4d_excits(idet,6);
                     lk(1) = pspace_find(sidx(29)%key, sidx(29)%nblock, pspace_key((/a,b,d,i,j/), 5, sidx(29)%dims, sidx(29)%chain))
                     lk(2) = pspace_find(sidx(30)%key, sidx(30)%nblock, pspace_key((/a,b,d,i,j/), 5, sidx(30)%dims, sidx(30)%chain))
                     lk(3) = pspace_find(sidx(31)%key, sidx(31)%nblock, pspace_key((/a,b,d,i,j/), 5, sidx(31)%dims, sidx(31)%chain))
                     lk(4) = pspace_find(sidx(32)%key, sidx(32)%nblock, pspace_key((/a,b,d,i,j/), 5, sidx(32)%dims, sidx(32)%chain))
                     lk(5) = pspace_find(sidx(33)%key, sidx(33)%nblock, pspace_key((/a,b,d,i,j/), 5, sidx(33)%dims, sidx(33)%chain))
                     lk(6) = pspace_find(sidx(34)%key, sidx(34)%nblock, pspace_key((/a,b,d,i,j/), 5, sidx(34)%dims, sidx(34)%chain))
                     lk(7) = pspace_find(sidx(35)%key, sidx(35)%nblock, pspace_key((/a,b,d,i,j/), 5, sidx(35)%dims, sidx(35)%chain))
                     lk(8) = pspace_find(sidx(36)%key, sidx(36)%nblock, pspace_key((/a,b,d,i,j/), 5, sidx(36)%dims, sidx(36)%chain))
                     lk(9) = pspace_find(sidx(37)%key, sidx(37)%nblock, pspace_key((/a,b,d,i,j/), 5, sidx(37)%dims, sidx(37)%chain))
                     lk(10) = pspace_find(sidx(38)%key, sidx(38)%nblock, pspace_key((/a,b,d,i,j/), 5, sidx(38)%dims, sidx(38)%chain))
                     lk(11) = pspace_find(sidx(39)%key, sidx(39)%nblock, pspace_key((/a,b,d,i,j/), 5, sidx(39)%dims, sidx(39)%chain))
                     lk(12) = pspace_find(sidx(40)%key, sidx(40)%nblock, pspace_key((/a,b,d,i,j/), 5, sidx(40)%dims, sidx(40)%chain))
                     lk(13) = pspace_find(sidx(41)%key, sidx(41)%nblock, pspace_key((/a,b,d,i,j/), 5, sidx(41)%dims, sidx(41)%chain))
                     lk(14) = pspace_find(sidx(42)%key, sidx(42)%nblock, pspace_key((/a,b,d,i,j/), 5, sidx(42)%dims, sidx(42)%chain))
                     lk(15) = pspace_find(sidx(43)%key, sidx(43)%nblock, pspace_key((/a,b,d,i,j/), 5, sidx(43)%dims, sidx(43)%chain))
                     lk(16) = pspace_find(sidx(44)%key, sidx(44)%nblock, pspace_key((/a,b,d,i,j/), 5, sidx(44)%dims, sidx(44)%chain))
                     lk(17) = pspace_find(sidx(45)%key, sidx(45)%nblock, pspace_key((/a,b,d,i,j/), 5, sidx(45)%dims, sidx(45)%chain))
                     ! +0.25 * I3C_vvvoov(abdijx) * tbb(xclk), q = (a,b,d,i,j), sign +1
                     idet = toff(kdx)
                     a = t4d_excits(idet,1); b = t4d_excits(idet,2); d = t4d_excits(idet,4); i = t4d_excits(idet,5); j = t4d_excits(idet,6);
                     anyx = .false.
                     idx = lk(1)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(29)%off(idx), sidx(29)%off(idx+1)-1
                        jdet = sidx(29)%perm(jj); w = bt4d_excits(jdet,4); u = bt4d_excits(jdet,7); v = bt4d_excits(jdet,8)
                        IX(:) = IX(:) + (1d0 * bt4d_amps(jdet)) * V2C_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(2)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(30)%off(idx), sidx(30)%off(idx+1)-1
                        jdet = sidx(30)%perm(jj); w = bt4d_excits(jdet,4); u = bt4d_excits(jdet,6); v = bt4d_excits(jdet,8)
                        IX(:) = IX(:) + (-1d0 * bt4d_amps(jdet)) * V2C_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(3)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(31)%off(idx), sidx(31)%off(idx+1)-1
                        jdet = sidx(31)%perm(jj); w = bt4d_excits(jdet,4); u = bt4d_excits(jdet,6); v = bt4d_excits(jdet,7)
                        IX(:) = IX(:) + (1d0 * bt4d_amps(jdet)) * V2C_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(4)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(32)%off(idx), sidx(32)%off(idx+1)-1
                        jdet = sidx(32)%perm(jj); w = bt4d_excits(jdet,3); u = bt4d_excits(jdet,7); v = bt4d_excits(jdet,8)
                        IX(:) = IX(:) + (-1d0 * bt4d_amps(jdet)) * V2C_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(5)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(33)%off(idx), sidx(33)%off(idx+1)-1
                        jdet = sidx(33)%perm(jj); w = bt4d_excits(jdet,3); u = bt4d_excits(jdet,6); v = bt4d_excits(jdet,8)
                        IX(:) = IX(:) + (1d0 * bt4d_amps(jdet)) * V2C_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(6)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(34)%off(idx), sidx(34)%off(idx+1)-1
                        jdet = sidx(34)%perm(jj); w = bt4d_excits(jdet,3); u = bt4d_excits(jdet,6); v = bt4d_excits(jdet,7)
                        IX(:) = IX(:) + (-1d0 * bt4d_amps(jdet)) * V2C_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(7)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(35)%off(idx), sidx(35)%off(idx+1)-1
                        jdet = sidx(35)%perm(jj); w = bt4d_excits(jdet,2); u = bt4d_excits(jdet,7); v = bt4d_excits(jdet,8)
                        IX(:) = IX(:) + (1d0 * bt4d_amps(jdet)) * V2C_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(8)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(36)%off(idx), sidx(36)%off(idx+1)-1
                        jdet = sidx(36)%perm(jj); w = bt4d_excits(jdet,2); u = bt4d_excits(jdet,6); v = bt4d_excits(jdet,8)
                        IX(:) = IX(:) + (-1d0 * bt4d_amps(jdet)) * V2C_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(9)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(37)%off(idx), sidx(37)%off(idx+1)-1
                        jdet = sidx(37)%perm(jj); w = bt4d_excits(jdet,2); u = bt4d_excits(jdet,6); v = bt4d_excits(jdet,7)
                        IX(:) = IX(:) + (1d0 * bt4d_amps(jdet)) * V2C_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(10)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(38)%off(idx), sidx(38)%off(idx+1)-1
                        jdet = sidx(38)%perm(jj); w = bt4c_excits(jdet,2); u = bt4c_excits(jdet,6); v = bt4c_excits(jdet,8)
                        IX(:) = IX(:) + (-1d0 * bt4c_amps(jdet)) * V2B_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(11)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(39)%off(idx), sidx(39)%off(idx+1)-1
                        jdet = sidx(39)%perm(jj); w = bt4c_excits(jdet,2); u = bt4c_excits(jdet,6); v = bt4c_excits(jdet,7)
                        IX(:) = IX(:) + (1d0 * bt4c_amps(jdet)) * V2B_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(12)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(40)%off(idx), sidx(40)%off(idx+1)-1
                        jdet = sidx(40)%perm(jj); w = bt4c_excits(jdet,2); u = bt4c_excits(jdet,5); v = bt4c_excits(jdet,8)
                        IX(:) = IX(:) + (1d0 * bt4c_amps(jdet)) * V2B_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(13)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(41)%off(idx), sidx(41)%off(idx+1)-1
                        jdet = sidx(41)%perm(jj); w = bt4c_excits(jdet,2); u = bt4c_excits(jdet,5); v = bt4c_excits(jdet,7)
                        IX(:) = IX(:) + (-1d0 * bt4c_amps(jdet)) * V2B_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(14)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(42)%off(idx), sidx(42)%off(idx+1)-1
                        jdet = sidx(42)%perm(jj); w = bt4c_excits(jdet,1); u = bt4c_excits(jdet,6); v = bt4c_excits(jdet,8)
                        IX(:) = IX(:) + (1d0 * bt4c_amps(jdet)) * V2B_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(15)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(43)%off(idx), sidx(43)%off(idx+1)-1
                        jdet = sidx(43)%perm(jj); w = bt4c_excits(jdet,1); u = bt4c_excits(jdet,6); v = bt4c_excits(jdet,7)
                        IX(:) = IX(:) + (-1d0 * bt4c_amps(jdet)) * V2B_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(16)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(44)%off(idx), sidx(44)%off(idx+1)-1
                        jdet = sidx(44)%perm(jj); w = bt4c_excits(jdet,1); u = bt4c_excits(jdet,5); v = bt4c_excits(jdet,8)
                        IX(:) = IX(:) + (-1d0 * bt4c_amps(jdet)) * V2B_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(17)
                     if (idx/=0) then
                        if (.not. anyx) then; IX(:) = 0.0d0; anyx = .true.; end if
                     do jj = sidx(45)%off(idx), sidx(45)%off(idx+1)-1
                        jdet = sidx(45)%perm(jj); w = bt4c_excits(jdet,1); u = bt4c_excits(jdet,5); v = bt4c_excits(jdet,7)
                        IX(:) = IX(:) + (1d0 * bt4c_amps(jdet)) * V2B_oovv_3012(:,u,v,w)
                     end do
                     end if
                     if (anyx) then
                     do idet = toff(kdx), toff(kdx+1)-1
                        c = t4d_excits(idet,3); k = t4d_excits(idet,7); l = t4d_excits(idet,8);
                        val = 0.0d0
                        do x = 1, nub
                           val = val + IX(x) * t2c(x,c,l,k)
                        end do
                        resid(idet) = resid(idet) + 1d0 * val
                     end do
                     end if
                  end do
                  !$omp end do
                  deallocate(IX)
                  !$omp end parallel
                  !!!! 5 passes on T4 sorted by columns (1,3,4,5,6)
                  tdims(1:5) = (/nua,nub,nub,noa,nob/)
                  tchain(1:5) = (/.false.,.false.,.true.,.false.,.false./)
                  call sort_pspace(t4d_excits, t4d_amps, n4abbb, 5, (/1,3,4,5,6/), tdims, tchain, tnblk, tkey, toff, resid)
                  ! q blocks grouped by their slice letters (counting sort of the blocks, T4 not moved)
                  allocate(trun(nub*noa+1), tcur(nub*noa), bord(tnblk))
                  trun = 0
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     tt = (t4d_excits(toff(kdx),3)-1)*noa + t4d_excits(toff(kdx),5)
                     trun(tt+1) = trun(tt+1) + 1
                  end do
                  trun(1) = 1
                  do tt = 1, nub*noa
                     trun(tt+1) = trun(tt) + trun(tt+1)
                  end do
                  tcur(:) = trun(1:nub*noa)
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     tt = (t4d_excits(toff(kdx),3)-1)*noa + t4d_excits(toff(kdx),5)
                     bord(tcur(tt)) = kdx; tcur(tt) = tcur(tt) + 1
                  end do
                  !$omp parallel default(shared) private(GB,RB,val,a,b,c,d,i,j,k,l,x,u,v,w,z,r,s,t,g,h,idet,kdx,irun,k0,nc,tt)
                  allocate(GB(noa,MAXC), RB(nub,MAXC))
                  !$omp do schedule(dynamic,4)
                  do irun = 1, nub*noa
                     do k0 = trun(irun), trun(irun+1)-1, MAXC
                        nc = min(MAXC, trun(irun+1)-k0)
                        do tt = 1, nc
                           idet = toff(bord(k0+tt-1))
                           a = t4d_excits(idet,1); c = t4d_excits(idet,3); d = t4d_excits(idet,4); i = t4d_excits(idet,5); j = t4d_excits(idet,6);
                           do u = 1, noa
                              GB(u,tt) = 1d0 * t2b(a,d,u,j)
                           end do
                        end do
                        RB(:,1:nc) = matmul(H2B_ovov_3012(:,:,c,i), GB(:,1:nc))
                        do tt = 1, nc
                           kdx = bord(k0+tt-1)
                           do idet = toff(kdx), toff(kdx+1)-1
                              b = t4d_excits(idet,2); k = t4d_excits(idet,7); l = t4d_excits(idet,8);
                              val = 0.0d0
                              do x = 1, nub
                                 val = val + RB(x,tt) * t2c(x,b,l,k)
                              end do
                              resid(idet) = resid(idet) - 1d0 * val
                           end do
                        end do
                     end do
                  end do
                  !$omp end do
                  deallocate(GB, RB)
                  !$omp end parallel
                  deallocate(trun, tcur, bord)
                  ! q blocks grouped by their slice letters (counting sort of the blocks, T4 not moved)
                  allocate(trun(nub*noa+1), tcur(nub*noa), bord(tnblk))
                  trun = 0
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     tt = (t4d_excits(toff(kdx),4)-1)*noa + t4d_excits(toff(kdx),5)
                     trun(tt+1) = trun(tt+1) + 1
                  end do
                  trun(1) = 1
                  do tt = 1, nub*noa
                     trun(tt+1) = trun(tt) + trun(tt+1)
                  end do
                  tcur(:) = trun(1:nub*noa)
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     tt = (t4d_excits(toff(kdx),4)-1)*noa + t4d_excits(toff(kdx),5)
                     bord(tcur(tt)) = kdx; tcur(tt) = tcur(tt) + 1
                  end do
                  !$omp parallel default(shared) private(GB,RB,val,a,b,c,d,i,j,k,l,x,u,v,w,z,r,s,t,g,h,idet,kdx,irun,k0,nc,tt)
                  allocate(GB(noa,MAXC), RB(nub,MAXC))
                  !$omp do schedule(dynamic,4)
                  do irun = 1, nub*noa
                     do k0 = trun(irun), trun(irun+1)-1, MAXC
                        nc = min(MAXC, trun(irun+1)-k0)
                        do tt = 1, nc
                           idet = toff(bord(k0+tt-1))
                           a = t4d_excits(idet,1); c = t4d_excits(idet,3); d = t4d_excits(idet,4); i = t4d_excits(idet,5); j = t4d_excits(idet,6);
                           do u = 1, noa
                              GB(u,tt) = 1d0 * t2b(a,c,u,j)
                           end do
                        end do
                        RB(:,1:nc) = matmul(H2B_ovov_3012(:,:,d,i), GB(:,1:nc))
                        do tt = 1, nc
                           kdx = bord(k0+tt-1)
                           do idet = toff(kdx), toff(kdx+1)-1
                              b = t4d_excits(idet,2); k = t4d_excits(idet,7); l = t4d_excits(idet,8);
                              val = 0.0d0
                              do x = 1, nub
                                 val = val + RB(x,tt) * t2c(x,b,l,k)
                              end do
                              resid(idet) = resid(idet) + 1d0 * val
                           end do
                        end do
                     end do
                  end do
                  !$omp end do
                  deallocate(GB, RB)
                  !$omp end parallel
                  deallocate(trun, tcur, bord)
                  ! q blocks grouped by their slice letters (counting sort of the blocks, T4 not moved)
                  allocate(trun(nub*nob+1), tcur(nub*nob), bord(tnblk))
                  trun = 0
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     tt = (t4d_excits(toff(kdx),3)-1)*nob + t4d_excits(toff(kdx),6)
                     trun(tt+1) = trun(tt+1) + 1
                  end do
                  trun(1) = 1
                  do tt = 1, nub*nob
                     trun(tt+1) = trun(tt) + trun(tt+1)
                  end do
                  tcur(:) = trun(1:nub*nob)
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     tt = (t4d_excits(toff(kdx),3)-1)*nob + t4d_excits(toff(kdx),6)
                     bord(tcur(tt)) = kdx; tcur(tt) = tcur(tt) + 1
                  end do
                  !$omp parallel default(shared) private(GB,RB,val,a,b,c,d,i,j,k,l,x,u,v,w,z,r,s,t,g,h,idet,kdx,irun,k0,nc,tt)
                  allocate(GB(nob,MAXC), RB(nub,MAXC))
                  !$omp do schedule(dynamic,4)
                  do irun = 1, nub*nob
                     do k0 = trun(irun), trun(irun+1)-1, MAXC
                        nc = min(MAXC, trun(irun+1)-k0)
                        do tt = 1, nc
                           idet = toff(bord(k0+tt-1))
                           a = t4d_excits(idet,1); c = t4d_excits(idet,3); d = t4d_excits(idet,4); i = t4d_excits(idet,5); j = t4d_excits(idet,6);
                           do u = 1, nob
