                     lk(4) = pspace_find(sidx(32)%key, sidx(32)%nblock, pspace_key((/a,c,d,i,j/), 5, sidx(32)%dims, sidx(32)%chain))
                     lk(5) = pspace_find(sidx(33)%key, sidx(33)%nblock, pspace_key((/a,c,d,i,j/), 5, sidx(33)%dims, sidx(33)%chain))
                     lk(6) = pspace_find(sidx(34)%key, sidx(34)%nblock, pspace_key((/a,c,d,i,j/), 5, sidx(34)%dims, sidx(34)%chain))
                     lk(7) = pspace_find(sidx(35)%key, sidx(35)%nblock, pspace_key((/a,c,d,i,j/), 5, sidx(35)%dims, sidx(35)%chain))
                     lk(8) = pspace_find(sidx(36)%key, sidx(36)%nblock, pspace_key((/a,c,d,i,j/), 5, sidx(36)%dims, sidx(36)%chain))
                     lk(9) = pspace_find(sidx(37)%key, sidx(37)%nblock, pspace_key((/a,c,d,i,j/), 5, sidx(37)%dims, sidx(37)%chain))
                     lk(10) = pspace_find(sidx(38)%key, sidx(38)%nblock, pspace_key((/a,c,d,i,j/), 5, sidx(38)%dims, sidx(38)%chain))
                     lk(11) = pspace_find(sidx(39)%key, sidx(39)%nblock, pspace_key((/a,c,d,i,j/), 5, sidx(39)%dims, sidx(39)%chain))
