                     lk(13) = pspace_find(sidx(41)%key, sidx(41)%nblock, pspace_key((/a,c,d,i,j/), 5, sidx(41)%dims, sidx(41)%chain))
                     lk(14) = pspace_find(sidx(42)%key, sidx(42)%nblock, pspace_key((/a,c,d,i,j/), 5, sidx(42)%dims, sidx(42)%chain))
                     lk(15) = pspace_find(sidx(43)%key, sidx(43)%nblock, pspace_key((/a,c,d,i,j/), 5, sidx(43)%dims, sidx(43)%chain))
                     lk(16) = pspace_find(sidx(44)%key, sidx(44)%nblock, pspace_key((/a,c,d,i,j/), 5, sidx(44)%dims, sidx(44)%chain))
                     lk(17) = pspace_find(sidx(45)%key, sidx(45)%nblock, pspace_key((/a,c,d,i,j/), 5, sidx(45)%dims, sidx(45)%chain))
                     ! +0.25 * I3C_vvvoov(abdijx) * tbb(xclk), q = (a,c,d,i,j), sign -1
